style.css:
@-moz-document domain("google.com"), domain("www.google.com") {
/* Fondo general */
body {
  background: #fce4ec url('https://i.pinimg.com/originals/2a/b2/54/2ab25462d8cb267e1148e0f7a927f2ae.png') no-repeat center bottom fixed !important;
  background-size: 300px !important;
  color: #4a4a4a !important;
  font-family: 'Comic Sans MS', 'Segoe UI', sans-serif !important;
}

/* Fondo del cuadro de búsqueda */
input.gLFyf {
  background-color: #fff0f5 !important;
  border: 2px solid #f8bbd0 !important;
  border-radius: 24px !important;
  color: #4a4a4a !important;
  padding: 10px !important;
}

/* Botones */
input[type="submit"], .RNmpXc {
  background-color: #f8bbd0 !important;
  color: #4a4a4a !important;
  border: none !important;
  border-radius: 20px !important;
  padding: 10px 16px !important;
  font-weight: bold !important;
}

/* Hover en botones */
input[type="submit"]:hover, .RNmpXc:hover {
  background-color: #f48fb1 !important;
}

/* Texto del pie de página */
#fbar, #fbar a {
  color: #4a4a4a !important;
  background-color: #fce4ec !important;
}

/* Ajuste del contenedor principal */
#searchform, form {
  background-color: transparent !important;
}

/* Fondo de sugerencias */
ul.erkvQe {
  background-color: #fff0f5 !important;
  border: 1px solid #f8bbd0 !important;
}

/* Sugerencias */
li.sbct, div.wM6W7d {
  background-color: #fce4ec !important;
  color: #4a4a4a !important;
}

/* Resultados de búsqueda */
#search {
  background-color: #fce4ec !important;
}

a {
  color: #c2185b !important;
}

/* Fondo de tarjetas de resultados */
.g, .tF2Cxc, .rc {
  background-color: #fce4ec !important;
  border: 1px solid #f8bbd0 !important;
  border-radius: 12px !important;
  padding: 10px !important;
}

/* Títulos y descripciones */
h3 {
  color: #880e4f !important;
}

span, .aCOpRe {
  color: #4a4a4a !important;
}
}
